def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    color_by_size = {3: 8, 5: 4, 7: 3}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            touches_edge = False

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                if cr == 0 or cc == 0 or cr == h - 1 or cc == w - 1:
                    touches_edge = True
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] == 0 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            if not touches_edge:
                size = max(max(x for x, _ in cells) - min(x for x, _ in cells) + 1,
                           max(y for _, y in cells) - min(y for _, y in cells) + 1)
                color = color_by_size.get(size)
                if color is not None:
                    for cr, cc in cells:
                        out[cr][cc] = color

    return out
